function peak(values) {
  if (values.length === 0) {
    return null;
  }
  var best = values[0];
  for (var i = 1; i < values.length; i++) {
    if (values[i] > best) {
      best = values[i];
    }
  }
  return best;
}

console.log(peak([88, 92, 79]));
console.log(peak([]));

exercise.solution:
function peak(values) {
  if (values.length === 0) return null;
  var best = values[0];
  for (var i = 1; i < values.length; i++) {
    if (values[i] > best) best = values[i];
  }
  return best;
}

console.log(peak([88, 92, 79]));
console.log(peak([]));

