function freq(text) {
  var counts = {};
  for (var i = 0; i < text.length; i++) {
    var ch = text[i];
    if (counts[ch] === undefined) {
      counts[ch] = 1;
    } else {
      counts[ch] = counts[ch] + 1;
    }
  }
  return counts;
}

